/bin/bash -lc "cat > /tmp/stroka-browser-check/check.mjs <<'EOF'
import {chromium} from 'playwright';
import assert from 'node:assert/strict';
const browser = await chromium.launch({headless:true,args:['--no-sandbox']});
const page = await browser.newPage({viewport:{width:1440,height:1080}});
const errors=[];
page.on('pageerror', error => errors.push(error.message));
await page.goto('http://localhost:5174');
await page.evaluate(() => document.fonts.ready);
await page.screenshot({path:'/tmp/stroka-desktop.png',fullPage:true});
console.log('Initial dimensions:', await page.locator('.editor-frame').boundingBox());
const source=page.locator('#markdown-content');
const preview=page.getByRole('article',{name:'Предпросмотр Markdown'});
await source.fill('# Проверка\\n\\n**Жирный** и *курсив*\\n\\n- пункт\\n\\n> Цитата\\n\\n[Ссылка](https://example.com)\\n\\n~~убрать~~\\n\\n- [x] Сделано\\n\\n| А | Б |\\n| --- | --- |\\n| 1 | 2 |\\n\\n"'```js'"\\nconst x = 1;\\n"'```'"');
assert.equal(await preview.locator('h1').textContent(),'Проверка');
assert.equal(await preview.locator('strong').textContent(),'Жирный');
assert.equal(await preview.locator('em').textContent(),'курсив');
assert.equal(await preview.locator('blockquote').textContent(),'\\nЦитата\\n');
assert.equal(await preview.locator('a').getAttribute('href'),'https://example.com');
assert.equal(await preview.locator('del').textContent(),'убрать');
assert.equal(await preview.locator('table').count(),1);
assert.equal(await preview.locator('input[type=\"checkbox\"]:checked').count(),1);
assert.equal(await preview.locator('pre code').textContent(),'const x = 1;\\n');
await source.fill('<script>window.markdownExecuted = true</script>\\n\\n[unsafe](javascript:alert(1))');
assert.equal(await preview.locator('script').count(),0);
assert.equal(await page.evaluate(()=>window.markdownExecuted),undefined);
assert.notEqual(await preview.locator('a').getAttribute('href'),'javascript:alert(1)');
await source.fill('Выделенный текст');
await source.evaluate(el=>el.setSelectionRange(0,10));
await page.getByRole('button',{name:'Жирный (Ctrl+B)',exact:true}).click();
assert.equal(await source.inputValue(),'**Выделенный** текст');
await source.fill('курсив');
await source.selectText();
await page.keyboard.press('Control+i');
assert.equal(await source.inputValue(),'*курсив*');
